+    payload: {
+      pending: [],
+      tiles: intensity && x === 13 && y === 7 ? { sample: [{
+        code: "example", prefecture: "検証県", municipality: "検証市", minimumMmPerHour: intensity,
+      }] } : {},
+    },
+  }))).flat();
+}
